css:
:host { display: block; box-sizing: border-box; font-family: var(--body); color: var(--ink); font-size: 14px; line-height: 1.5;
  --bg: #0F2444; --panel: #0F2444; --ink: #EDF1F7; --muted: #93A4BD; --line: #21395C;
  --focus: #E86A72; --btn: #D84048; --btn-ink: #ffffff;
  --hit: #34D399; --hit-bg: rgba(52,211,153,.14); --miss: #F87171; --miss-bg: rgba(248,113,113,.14); --live: #FBBF24; --live-bg: rgba(251,191,36,.14);
  --display: 'Press Start 2P', 'Courier New', monospace; --body: 'VT323', 'Courier New', monospace; }
*, *::before, *::after { box-sizing: inherit; }
[hidden] { display: none !important; }
h1 { font-family: var(--display); font-weight: 800; font-stretch: 112%; font-size: clamp(28px, 5.4vw, 52px); line-height: 1; letter-spacing: -0.015em; margin: 0 0 12px; }
h2 { font-family: var(--display); font-weight: 700; font-stretch: 105%; font-size: 20px; line-height: 1.2; margin: 0 0 12px; }
.lede { max-width: 66ch; color: var(--muted); margin: 0 0 20px; }
button:focus-visible, input:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }

.tabs { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 14px; }
.tab { appearance: none; border: 1px solid var(--line); background: transparent; color: var(--ink); font: inherit; font-weight: 600; padding: 10px 16px; border-radius: 999px; cursor: pointer; }
.tab[aria-pressed="true"] { background: var(--btn); color: var(--btn-ink); border-color: var(--btn); }
.tab small { font-weight: 400; opacity: .75; margin-left: 6px; }

/* ---------- broadcast stage ---------- */
.stage {
  --u: 10px; position: relative; width: 100%; aspect-ratio: 16 / 9; border-radius: 20px; overflow: hidden; color: #EAF1F7;
  background: radial-gradient(55% 48% at 14% 22%, rgba(216,64,72,.18), transparent 62%), radial-gradient(48% 44% at 88% 14%, rgba(96,165,250,.10), transparent 62%), radial-gradient(70% 55% at 50% 105%, rgba(10,34,71,.85), transparent 70%), #06152C;
}
.stage svg { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.hud { position: absolute; left: 50%; top: 2.4%; transform: translateX(-50%); width: 58%; display: grid; grid-template-columns: 1fr auto 1fr; align-items: stretch; background: rgba(8,13,22,.88); border-radius: calc(var(--u) * 1.1); overflow: hidden; z-index: 3; }
.hud .tm { display: flex; align-items: center; justify-content: space-between; gap: calc(var(--u) * 1); padding: calc(var(--u) * .7) calc(var(--u) * 1.6); border-bottom: calc(var(--u) * .45) solid var(--tc, #888); }
.hud .tm.home { flex-direction: row-reverse; }
.hud .ab { font-family: var(--display); font-weight: 800; font-stretch: 115%; font-size: calc(var(--u) * 2.5); line-height: 1; }
.hud .spc { font-size: calc(var(--u) * 1.15); font-weight: 800; color: #F5C542; min-width: 0; white-space: nowrap; text-align: center; }
.hud .spc.pk { color: #9DB0C1; }
.hud .sc { font-family: var(--display); font-weight: 900; font-stretch: 120%; font-size: calc(var(--u) * 4.6); line-height: 1; font-variant-numeric: tabular-nums; }
.hud .sc.bump { animation: bump .5s ease-out; }
@keyframes bump { 0% { transform: scale(1.4); } 100% { transform: scale(1); } }
.hud .mid { display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 0 calc(var(--u) * 1.8); background: rgba(255,255,255,.05); min-width: calc(var(--u) * 11); }
.hud .pd { font-size: calc(var(--u) * 1.35); color: #9DB0C1; font-weight: 600; }
.hud .ck { font-family: var(--display); font-weight: 800; font-stretch: 110%; font-size: calc(var(--u) * 3); font-variant-numeric: tabular-nums; line-height: 1.05; }
.panels { position: absolute; inset: 0; pointer-events: none; z-index: 2; }
.panel { position: absolute; top: 14%; width: 21%; background: rgba(8,13,22,.78); border-top: calc(var(--u) * .4) solid var(--tc, #888); border-radius: calc(var(--u) * 1); padding: calc(var(--u) * 1) calc(var(--u) * 1.2); font-size: calc(var(--u) * 1.3); line-height: 1.25; }
.panel.away { left: 1.4%; } .panel.home { right: 1.4%; }
.panel h3 { margin: 0 0 calc(var(--u) * .6); font-family: var(--display); font-weight: 800; font-stretch: 110%; font-size: calc(var(--u) * 1.7); display: flex; justify-content: space-between; align-items: baseline; }
.panel h3 span { font-family: var(--body); font-weight: 600; font-size: calc(var(--u) * 1.2); color: #9DB0C1; }
.panel .sec { color: var(--sec, #9DB0C1); font-weight: 700; font-size: calc(var(--u) * 1.15); margin: calc(var(--u) * .7) 0 calc(var(--u) * .2); }
.panel .row { display: flex; justify-content: space-between; gap: calc(var(--u) * .8); padding: calc(var(--u) * .12) calc(var(--u) * .3); border-radius: 4px; font-variant-numeric: tabular-nums; }
.panel .row b { font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.panel .row i { font-style: normal; color: #C8D5E0; white-space: nowrap; }
.panel .row.hot { background: rgba(255,255,255,.16); }
.panel .oi { color: #C8D5E0; font-size: calc(var(--u) * 1.1); line-height: 1.3; padding: 0 calc(var(--u) * .3); }
.panel .box { color: #F5C542; font-size: calc(var(--u) * 1.15); font-weight: 700; padding: 0 calc(var(--u) * .3); }
.cap { position: absolute; left: 50%; bottom: 4.6%; transform: translateX(-50%); max-width: 66%; min-width: 30%; display: none; align-items: center; gap: calc(var(--u) * 1); background: rgba(8,13,22,.88); border-left: calc(var(--u) * .45) solid var(--tc, #888); padding: calc(var(--u) * .8) calc(var(--u) * 1.6); border-radius: calc(var(--u) * .8); font-size: calc(var(--u) * 1.9); font-weight: 600; z-index: 3; }
.cap.on { display: flex; }
.chip { font-size: calc(var(--u) * 1.15); font-weight: 700; padding: calc(var(--u) * .2) calc(var(--u) * .8); border-radius: 999px; border: 1px solid rgba(255,255,255,.35); white-space: nowrap; }
.chip.warn { background: #F5C542; color: #1B1500; border-color: #F5C542; }
.chip.goal { background: #E6322B; border-color: #E6322B; color: #fff; }
.badge { position: absolute; right: 2%; bottom: 2.2%; font-size: max(10px, calc(var(--u) * 1.15)); color: #8AA0B3; z-index: 3; }
.big { position: absolute; left: 50%; top: 47%; transform: translate(-50%, -50%) skewX(-8deg); font-family: var(--display); font-weight: 900; font-stretch: 125%; font-size: calc(var(--u) * 7.5); letter-spacing: -0.01em; text-align: center; line-height: 1; opacity: 0; transition: opacity .3s ease; z-index: 3; text-shadow: 0 4px 24px rgba(0,0,0,.6); pointer-events: none; }
.big small { display: block; font-size: calc(var(--u) * 2.2); font-weight: 700; font-stretch: 100%; margin-top: calc(var(--u) * 1.2); letter-spacing: 0; }
.big.show { opacity: 1; }
.flash { position: absolute; inset: 0; opacity: 0; pointer-events: none; z-index: 1; background: radial-gradient(60% 55% at 50% 55%, var(--tc, #fff) 0%, transparent 70%); }
.flash.go { animation: flash 1.1s ease-out; }
@keyframes flash { 0% { opacity: .55; } 100% { opacity: 0; } }

@media (max-width: 760px) {
  .panel .oi, .panel .box { font-size: 12px; }
  .stage { overflow: visible; background: none; aspect-ratio: auto; }
  .stage .field { position: relative; aspect-ratio: 16 / 9; border-radius: 16px; overflow: hidden; background: radial-gradient(60% 55% at 50% 105%, rgba(30,80,140,.4), transparent 70%), #070C14; }
  .hud { width: 78%; top: 3%; }
  .panels { position: static; display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 8px; pointer-events: auto; }
  .panel { position: static; width: auto; font-size: 13px; background: #0B121D; color: #EAF1F7; }
  .panel h3 { font-size: 16px; } .panel h3 span { font-size: 12px; } .panel .sec { font-size: 12px; }
  .cap { font-size: max(11px, calc(var(--u) * 2.4)); max-width: 92%; bottom: 4%; }
  .badge { font-size: 9px; }
}
@media (min-width: 761px) { .stage .field { position: absolute; inset: 0; } }

.controls { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin: 16px 0 6px; }
.btn { appearance: none; border: 1px solid var(--btn); background: var(--btn); color: var(--btn-ink); font: inherit; font-weight: 700; padding: 10px 20px; border-radius: 999px; cursor: pointer; min-width: 92px; }
.btn.ghost { background: transparent; color: var(--ink); border-color: var(--line); font-weight: 600; min-width: 0; padding: 10px 14px; }
.btn[disabled] { opacity: .45; cursor: default; }
.seg { display: inline-flex; border: 1px solid var(--line); border-radius: 999px; overflow: hidden; }
.seg button { appearance: none; border: 0; background: transparent; color: var(--muted); font: inherit; font-weight: 600; padding: 9px 13px; cursor: pointer; }
.seg button[aria-pressed="true"] { background: var(--ink); color: var(--bg); }
.spacer { flex: 1 1 auto; }
.timeline { position: relative; padding: 18px 0 22px; }
.timeline input[type=range] { width: 100%; margin: 0; height: 22px; background: transparent; appearance: none; -webkit-appearance: none; position: relative; z-index: 2; }
.timeline input[type=range]::-webkit-slider-runnable-track { height: 6px; background: var(--line); border-radius: 3px; }
.timeline input[type=range]::-moz-range-track { height: 6px; background: var(--line); border-radius: 3px; }
.timeline input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; width: 18px; height: 18px; margin-top: -6px; border-radius: 50%; background: var(--ink); border: 3px solid var(--bg); }
.timeline input[type=range]::-moz-range-thumb { width: 14px; height: 14px; border-radius: 50%; background: var(--ink); border: 3px solid var(--bg); }
.ticks { position: absolute; left: 9px; right: 9px; top: 6px; height: 28px; z-index: 1; pointer-events: none; }
.tick { position: absolute; top: 0; width: 4px; height: 12px; margin-left: -2px; border-radius: 2px; background: var(--tc, var(--ink)); }
.tick::after { content: ""; position: absolute; left: -3px; top: -6px; width: 10px; height: 10px; border-radius: 50%; background: var(--tc, var(--ink)); border: 2px solid var(--bg); }
.pbar { position: absolute; left: 9px; right: 9px; top: 38px; display: grid; grid-template-columns: repeat(3, 1fr); color: var(--muted); font-size: 12px; pointer-events: none; }
.pbar span { border-left: 1px solid var(--line); padding-left: 6px; }

.lower { display: grid; gap: 36px; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); margin-top: 24px; }
.lower .wide { grid-column: 1 / -1; }
table { width: 100%; border-collapse: collapse; font-size: 14px; font-variant-numeric: tabular-nums; }
th, td { text-align: left; padding: 8px 6px; border-top: 1px solid var(--line); vertical-align: top; }
th { font-weight: 600; color: var(--muted); border-top: 0; }
td.n, th.n { text-align: right; }
.grp { color: var(--muted); font-size: 12px; }
.st { display: inline-block; padding: 1px 9px; border-radius: 999px; font-size: 12px; font-weight: 700; white-space: nowrap; }
.st.hit { color: var(--hit); background: var(--hit-bg); } .st.miss { color: var(--miss); background: var(--miss-bg); } .st.live { color: var(--live); background: var(--live-bg); }
.log { list-style: none; margin: 0; padding: 0; max-height: 360px; overflow: auto; }
.log li { padding: 8px 0; border-top: 1px solid var(--line); display: grid; grid-template-columns: 74px 1fr; gap: 10px; font-size: 14px; }
.log .w { color: var(--muted); font-variant-numeric: tabular-nums; }
.log li.g { font-weight: 700; }
.empty { color: var(--muted); margin: 0; padding: 12px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.bars { display: grid; gap: 8px; margin: 12px 0 0; }
.bar { display: grid; grid-template-columns: 52px 1fr 52px; gap: 10px; align-items: center; font-size: 14px; font-variant-numeric: tabular-nums; }
.bar i { display: block; height: 14px; border-radius: 3px; background: var(--tc); opacity: .55; }
.bar.me i { opacity: 1; } .bar.me span { font-weight: 700; } .bar span:last-child { text-align: right; }
.why p { margin: 0 0 12px; max-width: 62ch; } .why .fine { color: var(--muted); font-size: 14px; }
.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
@media (prefers-reduced-motion: reduce) { .hud .sc.bump, .flash.go { animation: none; } .big { transition: none; } }

.bs { margin-top: 14px; border: 1px solid var(--line); border-radius: 12px; padding: 10px 12px; background: var(--panel); }
.bs .bsw { overflow-x: auto; }
.bs table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; font-size: 14px; }
.bs th, .bs td { padding: 5px 7px; text-align: right; border-bottom: 1px solid var(--line); white-space: nowrap; background: transparent; }
.bs thead th { color: var(--muted); font-weight: 600; font-size: 12px; }
.bs th:first-child, .bs td:first-child { text-align: left; }
.bs tbody th { font-weight: 800; color: var(--ink); }
.bs td:last-child, .bs th:last-child { text-align: left; }
.bs .t { font-weight: 800; }
.bs ol { margin: 8px 0 0; padding: 0; list-style: none; font-size: 13px; color: var(--muted); display: grid; gap: 2px; }
.bs ol li b { color: var(--ink); }

.hud .spc:empty { display: none; }

.btn { border-radius: 8px; font-weight: 700; font-size: 13px; background: #D84048; border-color: #D84048; color: #fff; }
.btn:hover { background: #B8323A; border-color: #B8323A; }
.btn.ghost { background: #06152C; color: #EDF1F7; border-color: #5C7DB0; }
.btn.ghost:hover { background: #16304F; }
.seg { border-radius: 8px; }
.bs { border-radius: 12px; }

.seg button[aria-pressed="true"] { background: var(--btn); color: var(--btn-ink); }
.timeline input[type=range]::-webkit-slider-thumb { background: var(--btn); border-color: var(--bg); }
.timeline input[type=range]::-moz-range-thumb { background: var(--btn); border-color: var(--bg); }
.seg button { font-size: 12px; }

/* ---------- retro video game look ---------- */
.stage { border-radius: 10px; box-shadow: 0 0 0 4px #070b16, 0 0 0 7px #D84048; }
.stage::after { content: ""; position: absolute; inset: 0; pointer-events: none; z-index: 5; background: repeating-linear-gradient(0deg, rgba(0,0,0,.16) 0, rgba(0,0,0,.16) 1px, transparent 1px, transparent 3px); }
.hud { width: 72%; border-radius: 0; background: #070b16; box-shadow: 0 0 0 calc(var(--u) * .3) #e2e8f0, 0 0 0 calc(var(--u) * .6) #070b16; }
.hud .ab, .hud .sc, .hud .ck, .hud .pd, .hud .spc, .cap, .chip, .big, .badge { font-family: 'Press Start 2P', 'Courier New', monospace; font-stretch: normal; letter-spacing: 0; font-weight: 400; }
.hud .ab { font-size: max(9px, calc(var(--u) * 1.8)); }
.hud .sc { font-size: max(14px, calc(var(--u) * 3.2)); }
.hud .ck { font-size: max(10px, calc(var(--u) * 2.2)); }
.hud .pd { font-size: max(6px, calc(var(--u) * .95)); }
.hud .spc { font-size: max(6px, calc(var(--u) * .85)); }
.hud .tm { border-bottom-width: calc(var(--u) * .6); }
.cap { border-radius: 0; font-size: max(7px, calc(var(--u) * 1.2)); line-height: 1.6; box-shadow: 0 0 0 calc(var(--u) * .25) #070b16; border-left-width: calc(var(--u) * .7); max-width: 74%; }
.chip { font-size: max(6px, calc(var(--u) * .85)); border-radius: 0; }
.big { font-size: max(14px, calc(var(--u) * 4)); transform: translate(-50%, -50%); text-shadow: 4px 4px 0 #000; line-height: 1.4; }
.big small { font-size: max(8px, calc(var(--u) * 1.5)); font-weight: 400; margin-top: calc(var(--u) * 1.6); }
.badge { font-size: max(6px, calc(var(--u) * .8)); }
.tick { border-radius: 0; } .tick::after { border-radius: 0; }

/* ---------- logos ---------- */
.hud .ab { display: inline-flex; align-items: center; gap: calc(var(--u) * .8); }
.hud .crest { position: static; inset: auto; width: calc(var(--u) * 3 * var(--k, 1)); height: auto; display: block; flex: 0 0 auto; transform-origin: 50% 60%; }   /* the stage's rule that stretches every svg over the rink must not apply to crests */
.hud .crest.goal { animation: crestGoal .8s steps(1) 2; }
@keyframes crestGoal { 0%, 50%, 100% { transform: translateY(0); filter: none; } 25%, 75% { transform: translateY(-4px); filter: brightness(1.8); } }
.cil { animation: cilPulse 2.4s steps(1) infinite; transform-box: fill-box; transform-origin: center; }
@keyframes cilPulse { 0% { opacity: 1; } 50% { opacity: .78; } }
@media (prefers-reduced-motion: reduce) { .hud .crest.goal, .cil { animation: none; } }

/* animated team logos (same as the page, white sparkles on the dark scoreboard, a faster flip when the team scores) */
.logo-anim { --sp: #ffffff; position: relative; display: inline-block; line-height: 0; perspective: 160px; }
.logo-anim img { display: block; width: 100%; height: auto; animation: logoFlip 5s steps(12) infinite; }
.logo-anim::before, .logo-anim::after { content: ""; position: absolute; width: 2px; height: 2px; background: var(--sp); box-shadow: 2px 0 var(--sp), -2px 0 var(--sp), 0 2px var(--sp), 0 -2px var(--sp); opacity: 0; pointer-events: none; }
.logo-anim::before { top: -3px; right: -4px; animation: twinkle 2.6s steps(1) infinite; }
.logo-anim::after { left: -4px; bottom: 3px; animation: twinkle 2.6s steps(1) infinite; animation-delay: -1.3s; }
.hud .crest.goal img { animation: logoFlip .9s steps(12) 2; }
@keyframes logoFlip { 0%, 72% { transform: rotateY(0deg); } 100% { transform: rotateY(360deg); } }
@keyframes twinkle { 0%, 58% { opacity: 0; } 60%, 72% { opacity: 1; } 74%, 100% { opacity: 0; } }
@media (prefers-reduced-motion: reduce) { .logo-anim img, .logo-anim::before, .logo-anim::after, .hud .crest.goal img { animation: none; } }

/* official logos sit on a light tile so their black outlines do not vanish into the dark scoreboard */
.hud .logo-anim { background: #ffffff; padding: 2px; box-shadow: 0 0 0 2px #E86A72; }

/* ---------- readable pixel text in the replay (VT323 runs small, so sizes are scaled up) and pixel controls ---------- */
:host { font-size: 19px; line-height: 1.3; }
table, .bs table { font-size: 18px; }
.bs thead th { font-size: 15px; font-weight: 400; }
.bs th, .bs td { font-weight: 400; } .bs tbody th, .bs .t { font-weight: 400; }
.bs ol { font-size: 17px; }
.pbar { font-size: 15px; }
.btn { font-family: var(--display); font-weight: 400; font-size: 9px; border-radius: 0; letter-spacing: 0; padding: 12px 16px; line-height: 1.3; }
.btn.ghost { padding: 12px 14px; border-width: 2px; } .btn { border-width: 2px; }
.seg { border-radius: 0; border-width: 2px; }
.seg button { font-family: var(--display); font-weight: 400; font-size: 8px; padding: 11px 12px; letter-spacing: 0; }

.bs { background: #0F2444; }

