function startSim(ROOT, GAMES) {
  'use strict';
  var SVGNS = 'http://www.w3.org/2000/svg';
  var TOTAL = 3600, PERIOD = 1200;
  var calm = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches === true);

  function $(id) { return ROOT.getElementById(id); }
  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
  function lerp(a, b, u) { return a + (b - a) * u; }
  function ease(u) { return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2; }
  function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
  function pad2(n) { return (n < 10 ? '0' : '') + n; }
  function lastName(n) { var p = String(n).split(' '); return p.length > 1 ? p.slice(1).join(' ') : n; }
  function pct(p, d) { return (p * 100).toFixed(d === undefined ? 0 : d) + '%'; }
  function fmtPrice(a) { return a === null || a === undefined ? '' : (a > 0 ? '+' + a : String(a)); }
  function other(s) { return s === 'away' ? 'home' : 'away'; }
  function clockText(sec) {
    var p = Math.min(2, Math.floor(Math.min(sec, TOTAL - 0.001) / PERIOD));
    var rem = Math.max(0, PERIOD - (sec - p * PERIOD));
    return { p: p, text: Math.floor(rem / 60) + ':' + pad2(Math.floor(rem % 60)) };
  }
  function elapsedText(sec) { var m = Math.floor(sec / 60); return m + ':' + pad2(Math.floor(sec % 60)); }
  var ORD = ['1st', '2nd', '3rd'];
  var seedBase = 7;
  function rnd(i) { var x = Math.sin((i + seedBase) * 12.9898) * 43758.5453; return x - Math.floor(x); }

  /* ---------- perspective projection of the rink ---------- */
  var CX = 500, YT = 100, YB = 522, KX = 4.4, A = 0.55, INV_FAR = 1 / (1 + A);
  function proj(x, y) {
    var inv = 1 / (1 + A * (1 - y / 85));
    return { x: CX + (x - 100) * KX * inv, y: YT + (YB - YT) * (inv - INV_FAR) / (1 - INV_FAR), s: inv };
  }
  function poly(list, dy) {
    var d = dy || 0;
    return list.map(function (p) { var q = proj(p[0], p[1]); return q.x.toFixed(1) + ',' + (q.y + d).toFixed(1); }).join(' ');
  }
  function arcPts(cx, cy, r, a0, a1, n) {
    var o = []; for (var i = 0; i <= n; i++) { var a = a0 + (a1 - a0) * i / n; o.push([cx + r * Math.cos(a), cy + r * Math.sin(a)]); } return o;
  }
  function circlePts(cx, cy, r) { return arcPts(cx, cy, r, 0, 2 * Math.PI, 40); }
